    dead_zone_threshold = 0.5  # Adjusted from 0.1 to 0.5 to handle new environment
    if abs(vx) < dead_zone_threshold:
        fx = 0
    else:
        # Determine horizontal force based on position and velocity
        if pos.x < target_x_min:
            fx = 42  # Push right
        elif pos.x > target_x_max:
            fx = -42  # Push left
        else:
            # Apply force in the opposite direction of the velocity to slow it down
            if vx > 0:
                fx = -42
            elif vx < 0:
                fx = 42
            else:
                fx = 0

    # Apply vertical force only when moving down (vy < 0)
    if vy < 0:
        fy = 42
    else:
        fy = 0

    # Wind compensation only when outside the target x range
    wind_compensation = 0
    if pos.x < target_x_min:
        wind_compensation = 42  # Counteract wind pushing it left
    elif pos.x > target_x_max:
        wind_compensation = -42  # Counteract wind pushing it right

    # Combine forces
    final_fx = fx + wind_compensation
    final_fy = fy

    # Clamp to force limits
    if abs(final_fx) > 42:
        final_fx = 42 if final_fx > 0 else -42
    if abs(final_fy) > 42:
        final_fy = 42 if final_fy > 0 else -42

    # Apply forces
    sandbox.apply_force_to_seat(final_fx, final_fy)

