def build_agent(sandbox):
    # No structure is built; the task is solely about controlling the swing
    return None

def agent_action(sandbox, agent_body, step_count):
    seat = sandbox.get_swing_seat()
    if seat is None:
        return

    pos = seat.position
    vel = seat.linearVelocity
    vx = vel.x
    vy = vel.y

    target_y = 11.7
    force_mag = 42.0
    dead_zone_threshold = 0.3  # Lowered to allow more force application

    # Check if in dead zone (horizontal speed too low)
    if abs(vx) < dead_zone_threshold:
        return

    # Determine direction towards pivot
    if pos.x < 10.0:
        # Left side of pivot
        if vx > 0:
            horizontal_force = force_mag  # Moving away from pivot
        else:
            horizontal_force = -force_mag  # Moving towards pivot
    else:
        # Right side of pivot
        if vx < 0:
            horizontal_force = force_mag  # Moving towards pivot
        else:
            horizontal_force = -force_mag  # Moving away from pivot

    # Apply horizontal force
    sandbox.apply_force_to_seat(horizontal_force, 0)

    # Apply vertical force when descending (to slow down and gain height)
    if vy < 0:
        sandbox.apply_force_to_seat(0, force_mag)

    # Apply vertical boost at apex (low speed)
    if abs(vx) < 1.0 and abs(vy) < 1.0:
        sandbox.apply_force_to_seat(0, force_mag)
